INSERT INTO `_tbs_journal_guard`VALUES(COALESCE(@tbs_journal_ok,0));
INSERT INTO `tasks`(`id`,`type`,`duration`,`title`,`description`,`reward_text`,`reward_id_list`,`cash_reward`,`exp_reward`,`reward_method`,`min_level`,`max_level`,`min_players`,`max_players`,`repeatable`,`faction_reward`,`faction_amount`,`enabled`)SELECT e.`id`,e.`type`,e.`duration`,e.`title`,e.`description`,e.`reward_text`,e.`reward_id_list`,e.`cash_reward`,e.`exp_reward`,e.`reward_method`,e.`min_level`,e.`max_level`,e.`min_players`,e.`max_players`,e.`repeatable`,e.`faction_reward`,e.`faction_amount`,e.`enabled` FROM `_tbs_tasks` e WHERE @tbs_journal_ok=1 AND NOT EXISTS(SELECT 1 FROM `tasks` a WHERE a.`id`<=>e.`id`);
INSERT INTO `task_activities`(`taskid`,`activityid`,`req_activity_id`,`step`,`activitytype`,`target_name`,`goalmethod`,`goalcount`,`description_override`,`npc_match_list`,`item_id_list`,`zones`,`zone_version`,`spell_list`,`optional`,`min_x`,`max_x`,`min_y`,`max_y`,`min_z`,`max_z`)SELECT e.`taskid`,e.`activityid`,e.`req_activity_id`,e.`step`,e.`activitytype`,e.`target_name`,e.`goalmethod`,e.`goalcount`,e.`description_override`,e.`npc_match_list`,e.`item_id_list`,e.`zones`,e.`zone_version`,e.`spell_list`,e.`optional`,e.`min_x`,e.`max_x`,e.`min_y`,e.`max_y`,e.`min_z`,e.`max_z` FROM `_tbs_task_activities` e WHERE @tbs_journal_ok=1 AND NOT EXISTS(SELECT 1 FROM `task_activities` a WHERE a.`taskid`<=>e.`taskid` AND a.`activityid`<=>e.`activityid`);
INSERT INTO `achievement_criteria`(`achievement_id`,`component_type`,`component_sequence`,`component_id`,`event_type`,`progress_mode`,`behavior`,`target_id`,`target_id2`,`target_value`,`required_count`,`enabled`)SELECT e.`achievement_id`,e.`component_type`,e.`component_sequence`,e.`component_id`,e.`event_type`,e.`progress_mode`,e.`behavior`,e.`target_id`,e.`target_id2`,e.`target_value`,e.`required_count`,e.`enabled` FROM `_tbs_achievement_criteria` e WHERE @tbs_journal_ok=1 AND NOT EXISTS(SELECT 1 FROM `achievement_criteria` a WHERE a.`achievement_id`<=>e.`achievement_id` AND a.`component_type`<=>e.`component_type` AND a.`component_id`<=>e.`component_id`);
