-- Full39-route journal payload; disabled pending complete world/dependency activation.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_tbs_tasks`;
CREATE TEMPORARY TABLE `_tbs_tasks` LIKE `tasks`;
DROP TEMPORARY TABLE IF EXISTS `_tbs_task_activities`;
CREATE TEMPORARY TABLE `_tbs_task_activities` LIKE `task_activities`;
DROP TEMPORARY TABLE IF EXISTS `_tbs_achievement_criteria`;
CREATE TEMPORARY TABLE `_tbs_achievement_criteria` LIKE `achievement_criteria`;
DROP TEMPORARY TABLE IF EXISTS `_tbs_journal_guard`;
CREATE TEMPORARY TABLE `_tbs_journal_guard`(ok TINYINT NOT NULL CHECK(ok=1))ENGINE=InnoDB;
START TRANSACTION;
SET @tbs_journal_ok=
(COALESCE(@buriedsea_whole_batch_reviewed,0)=1)
